INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'd', '{"item":"d"}'::jsonb, NULL, 'd) análisis del inventario de la huella de agua:', 3, '{"letter":"d)","heading":"análisis del inventario de la huella de agua:","subitems":"1) procedimientos de recopilación de datos; 2) descripción cualitativa y cuantitativa de los procesos unitarios incluyendo detalles sobre datos individuales; 3) fuentes de datos, incluyendo el modelo o modelos utilizados y bibliografía; 4) procedimientos de cálculo; 5) validación de datos incluyendo: i) requisitos de calidad de los datos; ii) evaluación de la calidad de los datos; y iii) tratamiento de los datos que faltan; 6) análisis de sensibilidad para ajustar los límites del sistema; 7) principios y procedimientos de asignación que incluyen: i) documentación y justificación de los procedimientos de asignación; ii) aplicación uniforme de los procedimientos de asignación; 8) inventario del período utilizado como línea base, cuando sea pertinente;"}'::jsonb, 'd) análisis del inventario de la huella de agua:
1) procedimientos de recopilación de datos;
2) descripción cualitativa y cuantitativa de los procesos unitarios incluyendo detalles sobre datos individuales;
3) fuentes de datos, incluyendo el modelo o modelos utilizados y bibliografía;
4) procedimientos de cálculo;
5) validación de datos incluyendo:
i) requisitos de calidad de los datos;
ii) evaluación de la calidad de los datos; y
iii) tratamiento de los datos que faltan;
6) análisis de sensibilidad para ajustar los límites del sistema;
7) principios y procedimientos de asignación que incluyen:
i) documentación y justificación de los procedimientos de asignación;
ii) aplicación uniforme de los procedimientos de asignación;
8) inventario del período utilizado como línea base, cuando sea pertinente;' FROM regulation_tables WHERE standard_code = 'ISO-14046' AND edition = '2014' AND table_code = 'S6_2_TP'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'e', '{"item":"e"}'::jsonb, NULL, 'e) evaluación de la huella de agua, cuando aplique:', 4, '{"letter":"e)","heading":"evaluación de la huella de agua, cuando aplique:","subitems":"1) los procedimientos de evaluación del impacto, los cálculos y los resultados del estudio; 2) las limitaciones de los resultados de la evaluación del impacto relativos al objetivo y alcance definidos; 3) la relación de los resultados de la evaluación del impacto con el objetivo y el alcance definidos; 4) la relación de los resultados de la evaluación del impacto con los resultados del inventario; 5) las categorías de impacto e indicadores de categoría considerados, incluyendo las razones para su selección y una referencia a su fuente; 6) las descripciones o las referencias a todos los modelos de caracterización, factores de caracterización y métodos utilizados incluyendo todas las suposiciones y limitaciones; 7) descripciones o referencias a todas los juicios de valor utilizadas en relación con las categorías de impacto, modelos de caracterización, factores de caracterización, normalización, agrupamiento, ponderación y, en otras partes de la evaluación del impacto, la justificación para su uso y su influencia sobre los resultados, conclusiones y recomendaciones; 8) una declaración de que los resultados de la evaluación del impacto son expresiones relativas y no predicen los impactos en puntos finales de categoría, ni sobrepasan los umbrales, los márgenes de seguridad o riesgos; 9) y cuando se incluyen como una parte de la evaluación de la huella de agua, también: i) una descripción y justificación de la definición y descripción de cualquier categoría de impacto e indicadores de categoría o modelos de caracterización utilizados para la evaluación del impacto; ii) una declaración y justificación de cualquier agrupación de las categorías de impacto; iii) cualquier otro procedimiento que transforme los resultados del indicador y una justificación de las referencias seleccionadas, factores de ponderación, etc.; iv) cualquier análisis de los resultados del indicador, por ejemplo análisis de sensibilidad e incertidumbre o el uso de datos ambientales incluida cualquier implicación para los resultados; v) incertidumbre del método de evaluación del impacto de la huella de agua; y vi) los datos y resultados de indicadores obtenidos previamente a la normalización, agrupación o ponderación deben estar disponibles junto con los resultados normalizados, agrupados o ponderados;"}'::jsonb, 'e) evaluación de la huella de agua, cuando aplique:
1) los procedimientos de evaluación del impacto, los cálculos y los resultados del estudio;
2) las limitaciones de los resultados de la evaluación del impacto relativos al objetivo y alcance definidos;
3) la relación de los resultados de la evaluación del impacto con el objetivo y el alcance definidos;
4) la relación de los resultados de la evaluación del impacto con los resultados del inventario;
5) las categorías de impacto e indicadores de categoría considerados, incluyendo las razones para su selección y una referencia a su fuente;
6) las descripciones o las referencias a todos los modelos de caracterización, factores de caracterización y métodos utilizados incluyendo todas las suposiciones y limitaciones;
7) descripciones o referencias a todas los juicios de valor utilizadas en relación con las categorías de impacto, modelos de caracterización, factores de caracterización, normalización, agrupamiento, ponderación y, en otras partes de la evaluación del impacto, la justificación para su uso y su influencia sobre los resultados, conclusiones y recomendaciones;
8) una declaración de que los resultados de la evaluación del impacto son expresiones relativas y no predicen los impactos en puntos finales de categoría, ni sobrepasan los umbrales, los márgenes de seguridad o riesgos;
9) y cuando se incluyen como una parte de la evaluación de la huella de agua, también:
i) una descripción y justificación de la definición y descripción de cualquier categoría de impacto e indicadores de categoría o modelos de caracterización utilizados para la evaluación del impacto;
ii) una declaración y justificación de cualquier agrupación de las categorías de impacto;
iii) cualquier otro procedimiento que transforme los resultados del indicador y una justificación de las referencias seleccionadas, factores de ponderación, etc.;
iv) cualquier análisis de los resultados del indicador, por ejemplo análisis de sensibilidad e incertidumbre o el uso de datos ambientales incluida cualquier implicación para los resultados;
v) incertidumbre del método de evaluación del impacto de la huella de agua; y
vi) los datos y resultados de indicadores obtenidos previamente a la normalización, agrupación o ponderación deben estar disponibles junto con los resultados normalizados, agrupados o ponderados;' FROM regulation_tables WHERE standard_code = 'ISO-14046' AND edition = '2014' AND table_code = 'S6_2_TP'
